import java.util.Set;
import java.util.TreeSet;

import org.eclipse.rdf4j.common.annotation.InternalUseOnly;
import org.eclipse.rdf4j.query.algebra.TupleExpr;

/**
 * Immutable contract between hash-join planning and execution.
 *
 * <p>
 * Lookup bindings are nonconstant variables present in every row from both inputs and are therefore safe hash-key
 * components. Compatibility bindings are every nonconstant variable either input can emit and must all be checked
 * according to SPARQL solution-mapping compatibility after a bucket has been found.
 * </p>
 */
@InternalUseOnly
public final class HashJoinBindingContract {

	private static final HashJoinBindingContract EMPTY = new HashJoinBindingContract(List.of(), List.of());

	private final List<String> lookupBindings;
	private final List<String> compatibilityBindings;

	private HashJoinBindingContract(Collection<String> lookupBindings,
			Collection<String> compatibilityBindings) {
		List<String> normalizedCompatibility = sortedPlannerNames(compatibilityBindings);
		List<String> normalizedLookup = sortedPlannerNames(lookupBindings);
		if (!normalizedCompatibility.containsAll(normalizedLookup)) {
			throw new IllegalArgumentException("hash lookup bindings must be a subset of compatibility bindings");
		}
		this.lookupBindings = normalizedLookup;
		this.compatibilityBindings = normalizedCompatibility;
	}

	public static HashJoinBindingContract from(TupleExpr left, TupleExpr right) {
		return from(StreamBindingSchema.from(left), StreamBindingSchema.from(right));
	}

	public static HashJoinBindingContract from(StreamBindingSchema left, StreamBindingSchema right) {
		if (left == null || right == null) {
			return EMPTY;
		}
		Set<String> compatibility = new TreeSet<>(left.possible());
		compatibility.retainAll(right.possible());
		Set<String> lookup = new TreeSet<>(left.assured());
		lookup.retainAll(right.assured());
		return lookup.isEmpty() && compatibility.isEmpty()
				? EMPTY
				: new HashJoinBindingContract(lookup, compatibility);
	}

	/**
	 * Adapts the historical one-array API. Reserved planner names are discarded, and every remaining binding is used
	 * for both lookup and compatibility to preserve the old caller contract.
	 */
	public static HashJoinBindingContract legacy(String[] joinBindings) {
		if (joinBindings == null || joinBindings.length == 0) {
			return EMPTY;
		}
		List<String> bindings = sortedPlannerNames(List.of(joinBindings.clone()));
		return bindings.isEmpty() ? EMPTY : new HashJoinBindingContract(bindings, bindings);
	}

	public List<String> lookupBindings() {
		return lookupBindings;
	}

	public List<String> compatibilityBindings() {
		return compatibilityBindings;
	}

	public boolean hasLookupBindings() {
		return !lookupBindings.isEmpty();
	}

	private static List<String> sortedPlannerNames(Collection<String> names) {
		if (names == null || names.isEmpty()) {
			return List.of();
		}
		Set<String> sorted = new TreeSet<>();
		for (String name : names) {
			if (BindingUniverse.plannerName(name)) {
				sorted.add(name);
			}
		}
		return sorted.isEmpty() ? List.of() : List.copyOf(sorted);
	}
}
